            new ShipmentEntity { Id = 4, TrackingNumber = "SHP-20260604-10004", Origin = "Boston, MA", Destination = "Houston, TX", Status = ShipmentStatus.Delivered, ShippedDate = new DateTime(2026, 5, 28), EstimatedDelivery = new DateTime(2026, 6, 2), CustomerEmail = "customer1@example.com", Description = "Books - Bulk Order" },
            new ShipmentEntity { Id = 5, TrackingNumber = "SHP-20260605-10005", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.PickedUp, ShippedDate = new DateTime(2026, 6, 5), EstimatedDelivery = new DateTime(2026, 6, 9), CustomerEmail = "customer4@example.com", Description = "Auto Parts" }
